var usageSourceSchema = z15.strictObject({
  id: z15.string().uuid(),
  label,
  url: z15.string().max(2048),
  enabled: z15.boolean()
});
function usageSourceOrigin(value) {
  try {
    const url = new URL(value);
    if (url.username || url.password || url.search || url.hash || url.pathname !== "/") return null;
    const loopback = url.hostname === "localhost" || url.hostname === "127.0.0.1" || url.hostname === "[::1]";
    return url.protocol === "https:" || url.protocol === "http:" && loopback ? url.origin : null;
  } catch {
    return null;
  }
}
var usageSourceInputSchema = usageSourceSchema.extend({
  url: z15.string().max(2048).refine(
    (value) => usageSourceOrigin(value) !== null,
    "Use an HTTPS origin, or HTTP on localhost, without a path, query, or credentials."
  )
});
