// src/shared/release-repository.ts
var RELEASE_REPOSITORY_HOSTS = ["github.com", "gitlab.com"];
var RELEASE_REPOSITORY_URL_MAX_LENGTH = 500;
function releaseRepositoryLocation(value) {
  const trimmed = value.trim();
  if (!trimmed || trimmed.length > RELEASE_REPOSITORY_URL_MAX_LENGTH) return null;
  let parsed;
  try {
    parsed = new URL(trimmed);
  } catch {
    return null;
  }
  if (parsed.protocol !== "https:" || parsed.username || parsed.password || parsed.port) return null;
  const host = RELEASE_REPOSITORY_HOSTS.find((candidate2) => candidate2 === parsed.hostname.toLowerCase());
  if (!host) return null;
  const segments = parsed.pathname.replace(/\.git$/u, "").replace(/\/+$/u, "").split("/").filter(Boolean);
  return segments.length >= 2 ? { host, segments } : null;
}
function isReleaseRepositoryUrl(value) {
  return releaseRepositoryLocation(value) !== null;
}

