// src/server/persistence/required-row.ts
function requireRow(database, table, id, missing) {
  const row = cachedStatement(database, `SELECT * FROM ${table} WHERE id = ?`).get(id);
  if (!row) throw new RecordNotFoundError(missing);
  return row;
}

