import {
  chmod,
  lstat,
  open,
  readFile,
  rename,
  unlink
} from "node:fs/promises";
import { constants as constants4 } from "node:fs";
function throwIfAborted(signal) {
  if (signal?.aborted) {
    throw signal.reason instanceof Error ? signal.reason : new Error("The database recovery export was cancelled.");
  }
}
async function readDatabaseRecoveryExportFile(path2, options = {}) {
  throwIfAborted(options.signal);
  const metadata = await lstat(path2);
  throwIfAborted(options.signal);
  if (!metadata.isFile() || metadata.isSymbolicLink() || metadata.size < 1 || metadata.size > DATABASE_RECOVERY_EXPORT_MAX_BYTES) {
    throw new Error("The recovery export file is unavailable or too large.");
  }
  const noFollow = "O_NOFOLLOW" in constants4 ? FILE_OPEN_NO_FOLLOW : 0;
  const file = await open(path2, constants4.O_RDONLY | noFollow);
  try {
    const before = await file.stat();
    if (!before.isFile() || before.size !== metadata.size) {
      throw new Error("The recovery export file changed while opening.");
    }
    const content = await (options.operations?.readFile ?? readFile)(file, {
      encoding: "utf8",
      ...options.signal ? { signal: options.signal } : {}
    });
    throwIfAborted(options.signal);
    const after = await file.stat();
    if (after.size !== before.size || after.mtimeMs !== before.mtimeMs || after.ctimeMs !== before.ctimeMs) {
      throw new Error("The recovery export file changed while reading.");
    }
    return content;
  } finally {
    await file.close();
  }
}

